  "implementation": "def solve(case):
    # Validate case structure
    if not isinstance(case, dict):
        raise ValueError('case must be a dict')
    nodes = case.get('nodes')
    required_symbols = case.get('required_symbols')
    if not isinstance(nodes, list) or not isinstance(required_symbols, list):
        raise ValueError('nodes must be a list, required_symbols must be a list')
    for n in nodes:
        if not isinstance(n, dict):
            raise ValueError('each node must be a dict')
        for key in ('id', 'parent', 'symbol', 'depth', 'removable', 'utility'):
            if key not in n:
                raise ValueError(f'node missing key {key}')
        if not isinstance(n['id'], str) or not isinstance(n['symbol'], str):
            raise ValueError('id and symbol must be strings')
        if not isinstance(n['depth'], int) or not isinstance(n['removable'], bool):
            raise ValueError('depth must be int, removable must be bool')
        if n['parent'] is not None and not isinstance(n['parent'], str):
            raise ValueError('parent must be None or string')
    # Build node map, children map, find root
    node_by_id = {}
    children = {}
    root_id = None
    for n in nodes:
        nid = n['id']
        node_by_id[nid] = n
        children[nid] = []
    for n in nodes:
        pid = n['parent']
        if pid is not None:
            if pid not in node_by_id:
                raise ValueError(f'parent {pid} not found')
            children[pid].append(n['id'])
        else:
            if root_id is not None:
                raise ValueError('multiple roots')
            root_id = n['id']
    if root_id is None:
        raise ValueError('no root node (parent null)')
    req_symbols = set(required_symbols)
    retained = set(node_by_id.keys())
    removed = []
    # Sort nodes by depth descending, then id ascending
    sorted_ids = sorted(node_by_id.keys(), key=lambda nid: (-node_by_id[nid]['depth'], nid))
    for nid in sorted_ids:
        if nid not in retained:
            continue
        node = node_by_id[nid]
        if node['parent'] is None:
            continue  # never remove root
        if node['symbol'] in req_symbols:
            continue
        if not node['removable']:
            continue
        # Check children
        if any(cid in retained for cid in children[nid]):
            continue
        # Tentatively remove: check required symbols still present
        symbols_after = set()
        for rid in retained:
            if rid != nid:
                symbols_after.add(node_by_id[rid]['symbol'])
        if req_symbols.issubset(symbols_after):
            removed.append(nid)
            retained.remove(nid)
    removed_node_ids = removed
    retained_node_ids = sorted(retained)
    return {'removed_node_ids': removed_node_ids, 'retained_node_ids': retained_node_ids}
